  "knowledge": "Artifact Rarity & Valuation (ARV)",
  "description": "Establishes criteria for identifying artifacts of exceptional rarity and valuation.",
  "definition": "Artifacts are categorized with high rarity and valuation if their insurance value exceeds $1,000,000."
}

{
  "id": 56,
  "knowledge": "Conservation Priority Level",
  "description": "Classifies artifacts into priority levels based on their CPI scores.",
  "definition": "Based on the 'Conservation Priority Index (CPI)': 'High Priority' for scores > 7, 'Medium Priority' for scores between 4 and 7, and 'Low Priority' for scores <= 4."
}

{
  "id": 58,
  "knowledge": "Exposure Status",
  "description": "Determines whether an artifact's current humidity exceeds its defined sensitivity threshold.",
  "definition": "Classified as 'Over Exposure' if the current relative humidity exceeds the 'Humidity Exposure Thresholds' defined for its sensitivity level, otherwise 'Within Limits'."
}

{
  "id": 51,
  "knowledge": "High-Value Category",
  "description": "Classification system for categorizing high-value artifacts based on their monetary or cultural/historical significance.",
  "definition": "An artifact is 'Monetary High-Value' if its insurance value exceeds $1,000,000. It is 'Cultural/Historical High-Value' if its significance and cultural scores are in the top 10%. Otherwise, it is in the 'Other' category. This is derived from the 'High-Value Artifact' criteria."
}

